//! The editor as a Swift class, generated by BoltFFI: a thin wrapper over
//! the shared [`EditorApi`] in points (logical pixels), as UIKit and AppKit
//! measure.
//!
//! All calls happen on the main thread (Skia objects are not thread-safe),
//! hence `single_threaded`. Metal objects cross as raw pointers
//! (`Unmanaged.passUnretained(object).toOpaque()` as `UInt64`).

use rs_editor_api::{ApiOptions, EditorApi, Units};
use rs_editor_commands::KeyPlatform;
use rs_editor_view::{Insets, InteractionProfile};

pub struct NativeEditor {
    pub(crate) api: EditorApi,
    /// The Metal drawing surface (`metal.rs`).
    #[cfg(target_vendor = "apple")]
    surface: crate::metal::MetalSurface,
    /// VoiceOver (`access.rs`); dropped before the editor.
    #[cfg(any(target_os = "macos", target_os = "ios"))]
    accessibility: Option<crate::access::Accessibility>,
}

impl std::fmt::Debug for NativeEditor {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NativeEditor")
            .field("api", &self.api)
            .finish()
    }
}

#[boltffi::export(single_threaded)]
impl NativeEditor {
    /// An editor starting with `content`: a Tiptap JSON document, HTML,
    /// Markdown when `markdown`, or `""` for an empty document. Sizes are in
    /// points; `scale` is pixels per point. `touch` picks the iOS gestures
    /// (handles, magnifier, long press) over the mouse ones.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        width: f32,
        height: f32,
        scale: f32,
        dark: bool,
        content: String,
        markdown: bool,
        character_limit: i32,
        touch: bool,
    ) -> Self {
        Self {
            api: EditorApi::new(ApiOptions {
                width,
                height,
                scale,
                units: Units::Logical,
                dark,
                content,
                markdown,
                platform: KeyPlatform::Apple,
                profile: if touch {
                    InteractionProfile::ios()
                } else {
                    InteractionProfile::default()
                },
                // Room at the left for the drag handle's grip.
                padding: Insets {
                    top: 24.0,
                    right: 20.0,
                    bottom: 24.0,
                    left: 28.0,
                },
                character_limit: usize::try_from(character_limit).ok().filter(|&n| n > 0),
                ..Default::default()
            }),
            #[cfg(target_vendor = "apple")]
            surface: Default::default(),
            #[cfg(any(target_os = "macos", target_os = "ios"))]
            accessibility: None,
        }
    }

    // --- drawing -------------------------------------------------------------

    /// New size in points, and pixels per point.
    pub fn resize(&mut self, width: f32, height: f32, scale: f32) {
        self.api.resize(width, height, scale);
    }

    /// Starts drawing with Metal: `device` is an `MTLDevice`, `queue` an
    /// `MTLCommandQueue` of it. False when Skia could not use them.
    pub fn attach_metal(&mut self, device: u64, queue: u64) -> bool {
        #[cfg(target_vendor = "apple")]
        {
            // SAFETY: Swift passes its live device and queue.
            unsafe {
                self.surface.attach(
                    device as usize as *const std::ffi::c_void,
                    queue as usize as *const std::ffi::c_void,
                )
            }
        }
        #[cfg(not(target_vendor = "apple"))]
        {
            let _ = (device, queue);
            false
        }
    }

    /// Stops drawing (the view left its window).
    pub fn detach_metal(&mut self) {
        #[cfg(target_vendor = "apple")]
        self.surface.detach();
    }

    /// Draws a frame into `texture`, the `MTLTexture` of the layer's next
    /// drawable (`width` × `height` pixels, BGRA); Swift then presents the
    /// drawable on the same queue.
    pub fn render(&mut self, texture: u64, width: i32, height: i32) -> bool {
        #[cfg(target_vendor = "apple")]
        {
            // SAFETY: Swift passes the live texture of the drawable.
            let drawn = unsafe {
                self.surface.render(
                    self.api.view_mut(),
                    texture as usize as *const std::ffi::c_void,
                    width,
                    height,
                )
            };
            // What changed since the last frame, while VoiceOver listens.
            #[cfg(any(target_os = "macos", target_os = "ios"))]
            if let Some(accessibility) = self.accessibility.as_mut() {
                accessibility.update(self.api.view_mut());
            }
            drawn
        }
        #[cfg(not(target_vendor = "apple"))]
        {
            let _ = (texture, width, height);
            false
        }
    }

    /// Makes `view` (the editor's `NSView` or `UIView`, as a pointer)
    /// answer VoiceOver. The view must implement
    /// `@objc func rsEditorAccessibilityChanged()`, called after VoiceOver
    /// edits the document or moves the caret. Call once, before the view
    /// is shown.
    pub fn attach_accessibility(&mut self, view: u64) {
        #[cfg(any(target_os = "macos", target_os = "ios"))]
        if self.accessibility.is_none() && view != 0 {
            let editor: *mut NativeEditor = self;
            // SAFETY: Swift passes its live view, which owns this editor;
            // BoltFFI keeps the editor boxed at a stable address.
            self.accessibility = Some(unsafe {
                crate::access::Accessibility::attach(view as usize as *mut std::ffi::c_void, editor)
            });
        }
        #[cfg(not(any(target_os = "macos", target_os = "ios")))]
        let _ = view;
    }

    /// The window became key or stopped being key (VoiceOver follows the
    /// focused window on macOS).
    pub fn set_window_focused(&mut self, focused: bool) {
        #[cfg(any(target_os = "macos", target_os = "ios"))]
        if let Some(accessibility) = self.accessibility.as_mut() {
            accessibility.set_window_focused(focused);
        }
        #[cfg(not(any(target_os = "macos", target_os = "ios")))]
        let _ = focused;
    }

    /// Milliseconds until the view should draw again without input (an
    /// animation, the caret blink), or -1.
    pub fn next_frame_in(&self) -> i64 {
        self.api.next_frame_in()
    }

    // --- content and commands (the Tiptap API) ------------------------------

    /// The document as Tiptap JSON.
    pub fn get_json(&self) -> String {
        self.api.get_json()
    }

    /// The document as Tiptap-style HTML.
    pub fn get_html(&self) -> String {
        self.api.get_html()
    }

    /// Plain text, blocks separated by `\n`.
    pub fn get_text(&self) -> String {
        self.api.get_text()
    }

    /// The document as GitHub-flavored Markdown.
    pub fn get_markdown(&self) -> String {
        self.api.get_markdown()
    }

    /// Replaces the document with Tiptap JSON; false for invalid JSON.
    pub fn set_json(&mut self, json: String) -> bool {
        self.api.set_json(&json)
    }

    /// Replaces the document with HTML.
    pub fn set_html(&mut self, html: String) -> bool {
        self.api.set_html(&html)
    }

    /// Replaces the document with Markdown.
    pub fn set_markdown(&mut self, markdown: String) -> bool {
        self.api.set_markdown(&markdown)
    }

    pub fn is_empty(&self) -> bool {
        self.api.is_empty()
    }

    pub fn is_editable(&self) -> bool {
        self.api.is_editable()
    }

    pub fn set_editable(&mut self, editable: bool) {
        self.api.set_editable(editable);
    }

    /// Runs one command with JSON arguments; false when it did not apply.
    pub fn run(&mut self, name: String, args_json: String) -> bool {
        self.api.run(&name, &args_json)
    }

    /// Whether the command would apply.
    pub fn can(&mut self, name: String, args_json: String) -> bool {
        self.api.can(&name, &args_json)
    }

    /// Runs `[{name, args}]` as one transaction.
    pub fn run_chain(&mut self, steps_json: String) -> bool {
        self.api.run_chain(&steps_json)
    }

    pub fn can_chain(&mut self, steps_json: String) -> bool {
        self.api.can_chain(&steps_json)
    }

    /// Whether the mark or node `name` (with `attrs_json`) is active.
    pub fn is_active(&self, name: String, attrs_json: String) -> bool {
        self.api.is_active(&name, &attrs_json)
    }

    /// Attributes of the mark or node `name` at the selection, as JSON.
    pub fn get_attributes(&self, name: String) -> String {
        self.api.get_attributes(&name)
    }

    /// `{from, to, empty}` JSON.
    pub fn selection(&self) -> String {
        self.api.selection()
    }

    /// Changes whenever the document or the selection may have changed.
    pub fn revision(&self) -> u64 {
        self.api.revision()
    }

    /// Changes whenever the document changed.
    pub fn doc_revision(&self) -> u64 {
        self.api.doc_revision()
    }

    pub fn set_dark(&mut self, dark: bool) {
        self.api.set_dark(dark);
    }

    pub fn set_focused(&mut self, focused: bool) {
        self.api.set_focused(focused);
    }

    /// Height in points covered at the bottom (the keyboard on iOS).
    pub fn set_obscured_bottom(&mut self, points: f32) {
        self.api.set_obscured_bottom(points);
    }

    /// A formatting menu over text selected with a mouse (on by default).
    pub fn set_bubble_menu(&mut self, enabled: bool) {
        self.api.set_bubble_menu(enabled);
    }

    /// A grip beside blocks to select and move them (on by default).
    pub fn set_drag_handle(&mut self, enabled: bool) {
        self.api.set_drag_handle(enabled);
    }

    /// A menu of blocks when `/` is typed (on by default).
    pub fn set_slash_menu(&mut self, enabled: bool) {
        self.api.set_slash_menu(enabled);
    }

    /// The language of the editor's own menus (BCP 47).
    pub fn set_locale(&mut self, locale: String) {
        self.api.set_locale(&locale);
    }

    /// Text in an empty line with the caret; empty restores the default.
    pub fn set_placeholder(&mut self, text: String) {
        self.api.set_placeholder(&text);
    }

    /// Plain text pasted is read as Markdown.
    pub fn set_markdown_paste(&mut self, markdown: bool) {
        self.api.set_markdown_paste(markdown);
    }

    /// `{characters, words, limit}` JSON.
    pub fn character_count(&self) -> String {
        self.api.character_count()
    }

    /// Opens the link address field for the selection (Cmd-K).
    pub fn edit_link(&mut self) -> bool {
        self.api.edit_link()
    }

    // --- images and fonts ------------------------------------------------------

    /// The picture for an image reported by the `missingImages` effect:
    /// RGBA pixels (`premultiplied` or not), `scale` pixels per point.
    pub fn add_image(
        &mut self,
        src: String,
        rgba: Vec<u8>,
        width: u32,
        height: u32,
        scale: f32,
        premultiplied: bool,
    ) -> bool {
        self.api
            .add_image(&src, &rgba, width, height, scale, premultiplied)
    }

    /// The image at `src` could not be loaded.
    pub fn image_failed(&mut self, src: String) {
        self.api.image_failed(&src);
    }

    /// Whether the app picks images itself (`pickImage` effect).
    pub fn set_image_picker(&mut self, on: bool) {
        self.api.set_image_picker(on);
    }

    /// Adds a font (file bytes); returns its family, or `""`.
    pub fn add_font(&mut self, bytes: Vec<u8>, family: String) -> String {
        self.api.add_font(&bytes, &family)
    }

    // --- pointer, touch and scrolling -----------------------------------------

    /// A mouse event in points: `kind` 0 down, 1 move (dragged or not), 2
    /// up, 3 the pointer left; modifier bits 1 shift, 2 control, 4 option,
    /// 8 command.
    pub fn pointer(&mut self, kind: i32, x: f32, y: f32, clicks: u32, modifiers: u32) -> bool {
        self.api.pointer(kind, x, y, clicks, modifiers)
    }

    /// Scrolls by `dy` points with the pointer at `(x, y)`; `smooth`
    /// animates (mouse wheels), trackpads bring their own momentum.
    pub fn wheel(&mut self, x: f32, y: f32, dy: f32, smooth: bool) {
        self.api.wheel(x, y, dy, smooth);
    }

    /// A touch in points: `action` 0 down, 1 move, 2 up, 3 cancel.
    pub fn touch(&mut self, action: i32, x: f32, y: f32) {
        self.api.touch(action, x, y);
    }

    /// Effects since the last call, as a JSON array (see
    /// [`EditorApi::take_effects`]).
    pub fn take_effects(&mut self) -> String {
        self.api.take_effects()
    }

    /// A command chosen from the selection menu (`cut`, `copy`, `paste`,
    /// `selectAll`). For paste, the pasteboard's text and HTML (HTML wins).
    /// Returns `{text, html}` JSON to put on the pasteboard, or `""`.
    pub fn menu_action(
        &mut self,
        item: String,
        text: Option<String>,
        html: Option<String>,
    ) -> String {
        self.api
            .menu_action(&item, text.as_deref(), html.as_deref())
    }

    /// The system closed the selection menu.
    pub fn menu_dismissed(&mut self) {
        self.api.menu_dismissed();
    }

    // --- keys and text input ------------------------------------------------------

    /// A key as a W3C key name (`Backspace`, `ArrowLeft`, `b`) with
    /// modifier bits as in [`NativeEditor::pointer`]; whether the editor
    /// used it.
    pub fn key_down(&mut self, key: String, modifiers: u32) -> bool {
        self.api.key_down(&key, "", modifiers)
    }

    /// Typed text (`insertText` without a replacement range).
    pub fn insert_text(&mut self, text: String) -> bool {
        self.api.insert_text(&text)
    }

    /// Replaces `start..end` of the IME block with `text`; `composing`
    /// makes it the marked text (`setMarkedText`), else it is inserted
    /// (`insertText:replacementRange:`).
    pub fn replace_text(&mut self, start: i32, end: i32, text: String, composing: bool) -> bool {
        self.api.replace_text(start, end, &text, composing)
    }

    /// Commits the marked text as `text` (`insertText` while composing):
    /// with the composition, one undo step.
    pub fn commit_text(&mut self, text: String) {
        self.api.commit_text(&text);
    }

    /// Sets the marked text in place of the current one (or the selection).
    pub fn set_marked_text(&mut self, text: String) {
        self.api.set_composing_text(&text);
    }

    /// Ends the marked text, keeping it (`unmarkText`).
    pub fn unmark_text(&mut self) {
        self.api.finish_composing();
    }

    /// Selects `anchor..head` of the IME block (UTF-16 offsets).
    pub fn set_selection(&mut self, anchor: i32, head: i32) {
        self.api.set_selection(anchor, head);
    }

    /// The IME block as JSON: `{start, text, selection, composition,
    /// caret}` in points; `start` is -1 when no text takes input and -2
    /// for the link address field.
    pub fn ime_state(&mut self) -> String {
        self.api.ime_state()
    }

    /// The caret line and the bounds of each UTF-16 unit in `from..to`, in
    /// points (`firstRect(forCharacterRange:)`).
    pub fn ime_cursor_info(&mut self, from: i32, to: i32) -> String {
        self.api.ime_cursor_info(from, to)
    }

    /// The IME block offset at `(x, y)` points, or -1
    /// (`characterIndex(for:)`).
    pub fn ime_offset_at(&mut self, x: f32, y: f32) -> i32 {
        self.api.ime_offset_at(x, y)
    }

    // --- clipboard -----------------------------------------------------------------

    /// Copies or cuts the selection: `{text, html}` JSON (empty strings
    /// when nothing is selected).
    pub fn copy(&mut self, cut: bool) -> String {
        self.api.copy(cut)
    }

    /// Pastes plain text.
    pub fn paste(&mut self, text: String) -> bool {
        self.api.paste(&text)
    }

    /// Pastes pasteboard HTML; false when it held nothing usable.
    pub fn paste_html(&mut self, html: String) -> bool {
        self.api.paste_html(&html)
    }

    // --- accessibility -------------------------------------------------------------

    /// The accessibility tree as nested JSON (see
    /// [`EditorApi::accessibility_json`]), in points.
    pub fn accessibility_json(&mut self) -> String {
        self.api.accessibility_json()
    }

    /// Runs an accessibility action (`click`, `focus`, …) on node `id`.
    pub fn accessibility_action(&mut self, id: String, action: String) -> bool {
        self.api.accessibility_action(&id, &action)
    }
}
